"use strict";(self.webpackChunkdocs_scadys_io=self.webpackChunkdocs_scadys_io||[]).push([["2426"],{327(e){e.exports=JSON.parse('{"version":{"pluginId":"mdd400-v29","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"mdd400Sidebar":[{"type":"link","href":"/mdd400/v2.9/","label":"MDD400 Overview (v2.9)","docId":"index","unlisted":false},{"type":"link","href":"/mdd400/v2.9/quick-reference","label":"Quick Reference","docId":"quick-reference","unlisted":false},{"type":"category","label":"Circuit Design","items":[{"type":"link","href":"/mdd400/v2.9/circuit-design/esp32-module","label":"ESP32 Module","docId":"circuit-design/esp32-module","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/led-indicator","label":"LED Indicator","docId":"circuit-design/led-indicator","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/programming-socket","label":"Programming Socket","docId":"circuit-design/programming-socket","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/power-supplies","label":"Power Supplies","docId":"circuit-design/power-supplies","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/can-bus-power","label":"CAN Bus Power Protection","docId":"circuit-design/can-bus-power","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/can-transceiver","label":"CAN Transceiver","docId":"circuit-design/can-transceiver","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/display-interface","label":"Display Interface","docId":"circuit-design/display-interface","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/power-monitor","label":"Power Monitor","docId":"circuit-design/power-monitor","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/ambient-light-sensor","label":"Ambient Light Sensor","docId":"circuit-design/ambient-light-sensor","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/temperature-sensor","label":"Temperature Sensor","docId":"circuit-design/temperature-sensor","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/buzzer-driver","label":"Buzzer Driver","docId":"circuit-design/buzzer-driver","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/legacy-serial","label":"Legacy Serial Interface","docId":"circuit-design/legacy-serial","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/mdd400/v2.9/circuit-design/"},{"type":"category","label":"Firmware","items":[{"type":"link","href":"/mdd400/v2.9/firmware/","label":"Firmware","docId":"firmware/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Housing","items":[{"type":"link","href":"/mdd400/v2.9/housing/","label":"Housing","docId":"housing/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Compliance","items":[{"type":"link","href":"/mdd400/v2.9/compliance/","label":"Compliance","docId":"compliance/index","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"circuit-design/ambient-light-sensor":{"id":"circuit-design/ambient-light-sensor","title":"Ambient Light Sensor","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The OPT3004 has been bench-tested on this prototype: I\xb2C addressing, lux readout, and auto-ranging are functional. The V2.9 housing has a new aperture / lens window relative to the previous hardware revision, so the firmware\'s ALS-reading \u2192 DGUS II brightness lookup table needs to be re-fitted on this hardware before deployment \u2014 see the Display Interface page for the firmware-side brightness control loop.","sidebar":"mdd400Sidebar"},"circuit-design/buzzer-driver":{"id":"circuit-design/buzzer-driver","title":"Buzzer Driver","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/can-bus-power":{"id":"circuit-design/can-bus-power","title":"CAN Bus Power","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/can-transceiver":{"id":"circuit-design/can-transceiver","title":"CAN Transceiver","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/display-interface":{"id":"circuit-design/display-interface","title":"Display Interface","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The DWIN display has been driven end-to-end through DGUS II on this prototype: power-switching, the UART link, command issuance, and touch-event round-tripping are functional. Brightness control is firmware-driven from the on-board ambient light sensor; the V2.9 housing introduces a new ALS placement and the brightness lookup will need to be re-calibrated against the previous lookup curve, which was tuned over significant in-service open-ocean operating hours on a prior MDD400 hardware revision.","sidebar":"mdd400Sidebar"},"circuit-design/esp32-module":{"id":"circuit-design/esp32-module","title":"ESP32 Module","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The board is the developer/kit assembly variant. The firmware-programming hardware (J1 / U4 / D3 / D4 / D5 populated, R22 DNP) is documented on its own Programming Socket page.","sidebar":"mdd400Sidebar"},"circuit-design/index":{"id":"circuit-design/index","title":"Circuit Design","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/led-indicator":{"id":"circuit-design/led-indicator","title":"LED Indicator","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. Status LED has not yet been observed in a long-duration soak test; the bring-up check in this page\'s Testing & Verification section is required for first acceptance.","sidebar":"mdd400Sidebar"},"circuit-design/legacy-serial":{"id":"circuit-design/legacy-serial","title":"Legacy Serial Interface","description":"MDD400 v2.9 \u2014 Prototype \u2014 under test","sidebar":"mdd400Sidebar"},"circuit-design/pcb-markings":{"id":"circuit-design/pcb-markings","title":"PCB Markings & Compliance","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase"},"circuit-design/power-monitor":{"id":"circuit-design/power-monitor","title":"Power Monitor","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The INA219 has been bench-tested on this prototype: I\xb2C addressing, current reading, and bus-voltage reading are all functional. Quantitative accuracy checks against a reference instrument and the final firmware PGA selection are open bring-up items.","sidebar":"mdd400Sidebar"},"circuit-design/power-supplies":{"id":"circuit-design/power-supplies","title":"Power Supplies","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/programming-socket":{"id":"circuit-design/programming-socket","title":"Programming Socket","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The board is the developer/kit assembly variant currently fitted (U4 / D3 / D4 / D5 / J1 populated, R22 DNP). Production builds reverse the DNP pattern and use a pogo-pin fixture; that configuration is described in the Production variant section below.","sidebar":"mdd400Sidebar"},"circuit-design/temperature-sensor":{"id":"circuit-design/temperature-sensor","title":"Temperature Sensor","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The TMP112 has been bench-tested on this prototype: I\xb2C addressing and 12-bit temperature readout are functional. Long-duration thermal-soak measurements (solar load, enclosed-housing hot-soak) and firmware-side thermal protection logic remain as bring-up items.","sidebar":"mdd400Sidebar"},"compliance/index":{"id":"compliance/index","title":"Compliance","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"firmware/index":{"id":"firmware/index","title":"Firmware","description":"Hardware version","sidebar":"mdd400Sidebar"},"housing/index":{"id":"housing/index","title":"Housing","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"index":{"id":"index","title":"MDD400 Overview","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"quick-reference":{"id":"quick-reference","title":"Quick Reference","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"}}}}')}}]);